def search_range(nums, target):
    def find_bound(is_left):
        left, right = 0, len(nums) - 1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] > target or (is_left and target == nums[mid]):
                right = mid - 1
            else:
                left = mid + 1
        return left

    left_idx = find_bound(True)
    if left_idx == len(nums) or nums[left_idx] != target:
        return [-1, -1]
    return [left_idx, find_bound(False) - 1]

