class HashTable:
    def __init__(self):
        self.table = [None] * 100

    def _hash(self, key):
        return hash(key) % len(self.table)

    def insert(self, key, value):
        index = self._hash(key)
        self.table[index] = value

    def search(self, key):
        index = self._hash(key)
        return self.table[index]

